from taf.internal.gnb.oam.rap.client.rap.v2 import SWMApi, ApiClient, Configuration

import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SwmV1(object):

    def __init__(self, con_details, access_token):
        self.configuration = self._create_configuration_prepare(con_details)
        self.configuration.access_token = access_token
        self.swm_api_instance = SWMApi(ApiClient(self.configuration))

    @staticmethod
    def _create_configuration_prepare(con_details):
        config_object = Configuration()
        config_object.host = con_details.make_configuration_host(original_endpoint=config_object.host)
        config_object.retries = 0
        config_object.verify_ssl = con_details.secure
        return config_object

    def get_active_software_info(self):
        return self.swm_api_instance.swm_software_active_get()

    def get_passive_software_info(self):
        return self.swm_api_instance.swm_software_passive_get()

    def get_factory_software_info(self):
        return self.swm_api_instance.swm_software_factory_get()

    def get_all_software_packages(self):
        return self.swm_api_instance.swm_software_get()
